<style>
.kbHero{padding:76px 0 48px;text-align:center;background:radial-gradient(700px 320px at 50% 0,rgba(61,141,255,.2),transparent 72%);border-bottom:1px solid #11263b}.kbHero h1{font-size:clamp(38px,6vw,62px);margin:8px 0 10px}.kbHero p{color:#8fa3bd;max-width:700px;margin:0 auto}.kbSearch{max-width:760px;margin:28px auto 0;display:flex;gap:10px;padding:8px;border:1px solid #1f3d5a;background:#071522;border-radius:16px;box-shadow:0 18px 55px rgba(0,0,0,.24)}.kbSearch input{flex:1;min-width:0;background:transparent;border:0;color:#fff;padding:0 13px;font:inherit;outline:none}.kbSearch button{min-width:120px}.kbShell{padding:54px 0 78px}.kbGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.kbCategory{display:block;padding:22px;border:1px solid #18324c;border-radius:17px;background:linear-gradient(145deg,#0c1b2c,#081522);transition:.16s ease}.kbCategory:hover{transform:translateY(-2px);border-color:#315d86}.kbCategoryTop{display:flex;align-items:center;justify-content:space-between;gap:12px}.kbCatIcon{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:#102a43;border:1px solid #245177;color:#8ed2ff}.kbCount{font-size:10px;font-weight:900;color:#6e8ba8;background:#08131f;border:1px solid #17314b;border-radius:999px;padding:6px 9px}.kbCategory h3{margin:15px 0 5px;font-size:18px}.kbCategory p{margin:0;color:#8198b3;font-size:13px}.kbArticleLinks{display:grid;gap:7px;margin-top:16px;padding-top:14px;border-top:1px solid #142b42}.kbArticleLinks span{display:block;color:#adc2d8;font-size:12px}.kbSection{margin-top:48px}.kbSectionHead{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:18px}.kbSectionHead h2{font-size:28px;margin:4px 0}.kbArticleList{display:grid;gap:9px}.kbArticleRow{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 18px;border:1px solid #17314b;background:#081522;border-radius:13px;transition:.16s ease}.kbArticleRow:hover{border-color:#2c557c